j:jelly.g2:evaluate:
    var rotaSysId = ${jvar_ref_table}.rota;
	var rosters = new OnCallMemberUtils().getRostersWithMembers(rotaSysId);
	rosters;

j:jelly.script:
function onChangeDate(ctrl, oldValue, newValue) {
	var selDate = new Date(newValue);
     document.querySelectorAll('.roster-member').forEach(function($member){
			$member.style.display = "block";
 			var from = $member.getAttribute('data-from');
			var to = $member.getAttribute('data-to');
			if (from $[AND] new Date(from).getTime() &gt; selDate.getTime())
					$member.style.display = "none";	
			if (to $[AND] new Date(to).getTime() &lt; selDate.getTime())
					$member.style.display = "none";	
	});
}
g_event_handlers.push(new GlideEventHandler('onChange_on_call_add_member.from_date', onChangeDate, 'on_call_add_member.from_date'));
g_event_handlers.push(new GlideEventHandler('onChange_on_call_remove_member.from_date', onChangeDate, 'on_call_remove_member.from_date'));
g_event_handlers.push(new GlideEventHandler('onChange_on_call_swap_member.from_date', onChangeDate, 'on_call_swap_member.from_date'));
